"""Lightweight wall-clock stage logs for ASR / Demucs pipelines."""

from __future__ import annotations

import logging
import time
from typing import Any

_log = logging.getLogger("transub_engine.asr.stage_clock")


class StageClock:
    """Accumulate named stage durations and emit one summary line."""

    def __init__(self, label: str) -> None:
        self.label = str(label or "stage")
        self._t0 = time.perf_counter()
        self._marks: list[tuple[str, float]] = []

    def mark(self, name: str) -> float:
        now = time.perf_counter()
        prev = self._marks[-1][1] if self._marks else self._t0
        dt = now - prev
        self._marks.append((str(name), now))
        return dt

    def log_mark(self, name: str, **extra: Any) -> float:
        dt = self.mark(name)
        tail = "".join(f" | {k}={v}" for k, v in extra.items() if v is not None)
        _log.info("stage %s: %s %.2fs%s", self.label, name, dt, tail)
        return dt

    def total_s(self) -> float:
        return time.perf_counter() - self._t0

    def summary(self) -> str:
        parts: list[str] = []
        prev = self._t0
        for name, ts in self._marks:
            parts.append(f"{name}={ts - prev:.2f}s")
            prev = ts
        parts.append(f"total={self.total_s():.2f}s")
        return " ".join(parts)

    def log_summary(self) -> None:
        _log.info("stage %s summary: %s", self.label, self.summary())
